WITH invalidated AS ( UPDATE calendar_backfill_jobs SET status = 'failed', completed_at = now(), lease_token = NULL, lease_expires_at = NULL, last_error = 'superseded by a newer Google grant', updated_at = now() WHERE email_link_id = $1 AND kind = 'google_calendar' AND grant_version <> $2 AND status IN ('pending', 'running') RETURNING id ) UPDATE calendar_sync_outbox outbox SET published_at = COALESCE(outbox.published_at, now()) FROM invalidated WHERE outbox.backfill_job_id = invalidated.id
